#include<bits/stdc++.h>
#define elif else if
using namespace std;
int n,m,ans=INT_MAX;
pair<int,int> start;
unordered_map<char,pair<pair<int,int>,pair<int,int> > > csm;
vector<char> a[200005];
void dfs(int x,int y,int z){
    if(a[x][y]=='T'){
        ans=min(ans,z);
        return;
    }
    if(x>1)if(a[x-1][y]!='#'){
        char l=a[x-1][y];
        a[x-1][y]='#';
        dfs(x-1,y,z+1);
        if(a[x-1][y]!='.'){
            if(make_pair(x-1,y)==csm[a[x-1][y]].first){
                char k1=a[csm[a[x-1][y]].second.first][csm[a[x-1][y]].second.second];
                a[csm[a[x-1][y]].second.first][csm[a[x-1][y]].second.second]='#';
                dfs(csm[a[x-1][y]].second.first,csm[a[x-1][y]].second.second,z+1);
                a[csm[a[x-1][y]].second.first][csm[a[x-1][y]].second.second]=k1;
            }
            else{
                char k2=a[csm[a[x-1][y]].first.first][csm[a[x-1][y]].first.second];
                a[csm[a[x-1][y]].first.first][csm[a[x-1][y]].first.second]='#';
                dfs(csm[a[x-1][y]].first.first,csm[a[x-1][y]].first.second,z+1);
                a[csm[a[x-1][y]].first.first][csm[a[x-1][y]].first.second]=k2;
            }
        }
        a[x-1][y]=l;
    }
    if(x<n)if(a[x+1][y]!='#'){
        char l=a[x+1][y];
        a[x+1][y]='#';
        dfs(x+1,y,z+1);
        if(a[x+1][y]!='.'){
            if(make_pair(x+1,y)==csm[a[x+1][y]].first){
                char k1=a[csm[a[x+1][y]].second.first][csm[a[x+1][y]].second.second];
                a[csm[a[x+1][y]].second.first][csm[a[x+1][y]].second.second]='#';
                dfs(csm[a[x+1][y]].second.first,csm[a[x+1][y]].second.second,z+1);
                a[csm[a[x+1][y]].second.first][csm[a[x+1][y]].second.second]=k1;
            }
            else{
                char k2=a[csm[a[x+1][y]].first.first][csm[a[x+1][y]].first.second];
                a[csm[a[x+1][y]].first.first][csm[a[x+1][y]].first.second]='#';
                dfs(csm[a[x+1][y]].first.first,csm[a[x+1][y]].first.second,z+1);
                a[csm[a[x+1][y]].first.first][csm[a[x+1][y]].first.second]=k2;
            }
        }
        a[x+1][y]=l;
    }
    if(y>1)if(a[x][y-1]!='#'){
        char l=a[x][y-1];
        a[x][y-1]='#';
        dfs(x,y-1,z+1);
        if(a[x][y-1]!='.'){
            if(make_pair(x,y-1)==csm[a[x][y-1]].first){
                char k1=a[csm[a[x][y-1]].second.first][csm[a[x][y-1]].second.second];
                a[csm[a[x][y-1]].second.first][csm[a[x][y-1]].second.second]='#';
                dfs(csm[a[x][y-1]].second.first,csm[a[x][y-1]].second.second,z+1);
                a[csm[a[x][y-1]].second.first][csm[a[x][y-1]].second.second]=k1;
            }
            else{
                char k2=a[csm[a[x][y-1]].first.first][csm[a[x][y-1]].first.second];
                a[csm[a[x][y-1]].first.first][csm[a[x][y-1]].first.second]='#';
                dfs(csm[a[x][y-1]].first.first,csm[a[x][y-1]].first.second,z+1);
                a[csm[a[x][y-1]].first.first][csm[a[x][y-1]].first.second]=k2;
            }
        }
        a[x][y-1]=l;
    }
    if(y<m)if(a[x][y+1]!='#'){
        char l=a[x][y+1];
        a[x][y+1]='#';
        dfs(x,y+1,z+1);
        if(a[x][y+1]!='.'){
            if(make_pair(x,y+1)==csm[a[x][y+1]].first){
                char k1=a[csm[a[x][y+1]].second.first][csm[a[x][y+1]].second.second];
                a[csm[a[x][y+1]].second.first][csm[a[x][y+1]].second.second]='#';
                dfs(csm[a[x][y+1]].second.first,csm[a[x][y+1]].second.second,z+1);
                a[csm[a[x][y+1]].second.first][csm[a[x][y+1]].second.second]=k1;
            }
            else{
                char k2=a[csm[a[x][y+1]].first.first][csm[a[x][y+1]].first.second];
                a[csm[a[x][y+1]].first.first][csm[a[x][y+1]].first.second]='#';
                dfs(csm[a[x][y+1]].first.first,csm[a[x][y+1]].first.second,z+1);
                a[csm[a[x][y+1]].first.first][csm[a[x][y+1]].first.second]=k2;
            }
        }
        a[x][y+1]=l;
    }
}
signed main(){
    ios::sync_with_stdio(0);
    cin.tie(0);cout.tie(0);
    cin>>n>>m;
    for(int i=1;i<=n;i++){
        for(int j=1;j<=m;j++){
            char c;
            cin>>c;
            if(c=='S') start={i,j};
            elif(c!='F'&&c!='.'&&c!='#'){
                if(csm[c].first.first==0)
                    csm[c].first={i,j};
                else
                    csm[c].second={i,j};
            }
            a[i].push_back(c);
        }
    }
    a[start.first][start.second]='#';
    dfs(start.first,start.second,0);
    return 0;
}
